import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnChanges, OnDestroy, OnInit, Output, SimpleChanges, ViewChild } from '@angular/core';
import { FactTableComponent } from '../../../../shared/components/fact-table/fact-table.component';
import { WorkspaceService } from '../../../services/workspace/workspace.service';
import { FactfileRes, factlistRes, IssuecategoryRes, IssueRes, tablecols, } from '../../../interfaces/workspace.interface';
import { EmptyComponent } from '../../../../shared/components/empty/empty.component';
import { SkeletonComponent } from '../../../../shared/components/skeleton/skeleton.component';
import { Subject, Subscription } from 'rxjs';
import { myTeamUsers, toolEvents } from '../../../../pdf/interfaces/pdf.interface';
import { finalFilterList } from '../../../../shared/interfaces/filter.interface';
import { CommonService } from '../../../../shared/services/common/common.service';
import { MatExpansionModule } from '@angular/material/expansion';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { CdkVirtualScrollViewport, ScrollingModule } from '@angular/cdk/scrolling';
import { NgScrollbarModule } from 'ngx-scrollbar';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { FactsheetService } from '../../../services/factsheet/factsheet.service';
import { PreviewComponent } from '../../../../shared/components/myfiles/preview/preview.component';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'workspace-chronology',
  standalone: true,
  imports: [MatExpansionModule, FactTableComponent, EmptyComponent, SkeletonComponent, IconComponent,
    ScrollingModule, NgScrollbarModule, CommonModule, FormsModule, PreviewComponent, TranslateModule
  ],
  templateUrl: './workspace-chronology.component.html',
  styleUrl: './workspace-chronology.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class WorkspaceChronologyComponent implements OnInit, OnChanges, OnDestroy {
  public showsource: any = null;
  // Dropdown filter selections
  selectedType: string = '';
  selectedIssue: string = '';
  selectedContact: string = '';

  // Dropdown options
  get typeOptions(): string[] {
    const allTypes = [...this.allFacts, ...this.allQuickFacts]
      .map(f => f.cFiletype)
      .filter(Boolean);
    return Array.from(new Set(allTypes));
  }
  get issueOptions(): string[] {
    const allSubIssues = [...this.allFacts, ...this.allQuickFacts]
      .flatMap(f => (f.issues || []))
      .flatMap(cat => (cat.sublist || []));
    return Array.from(new Set(allSubIssues.map(i => i.cIName).filter(Boolean)));
  }
  get contactOptions(): string[] {
    return [];
  }

  onFilterDropdownChange() {
    // Remove previous TYPE, ISSUE, CONTACT filters
    this.jFilter = this.jFilter.filter(f => !['TYPE', 'ISSUE', 'CONTACT'].includes(f.name));
    if (this.selectedType) {
      this.jFilter.push({ name: 'TYPE', type: 'V', value: [this.selectedType] });
    }
    if (this.selectedIssue) {
      this.jFilter.push({ name: 'ISSUE', type: 'V', value: [this.selectedIssue] });
    }
    if (this.selectedContact) {
      this.jFilter.push({ name: 'CONTACT', type: 'V', value: [this.selectedContact] });
    }
    // Server-side filtering
    this.getFactlist(0, 0);
    this.cdr.detectChanges();
  }
  sidebarSection: string = 'issues';
  impactImgErrorMap: { [key: string]: boolean } = {};

  onImpactImgError(event: Event) {
    const imgElem = event.target as HTMLImageElement;
    if (imgElem?.src) {
      imgElem.style.display = 'none';
    }
  }

  @ViewChild(CdkVirtualScrollViewport) viewport: CdkVirtualScrollViewport;
  @Input() nCaseid: string;
  @Input() activetab: string;
  @Input() isFact: boolean;
  @Input() isQFact: boolean;
  @Input() isCritical: boolean;
  @Input() isHeavily: boolean;
  @Input() tablecols: tablecols[];
  @Input() noteSearchText: string = ''; // For highlighting search terms
  @Input() onWorkspaceEvent: Subject<toolEvents>;
  @Output() OnEvent = new EventEmitter<toolEvents>();
  factlist: factlistRes[] = [];
  quickfactlist: factlistRes[] = [];
  allFacts: factlistRes[] = [];
  allQuickFacts: factlistRes[] = [];
  selectedFact: factlistRes | null = null;
  selectedIssues: IssueRes[] = [];
  factLinks: any[] = [];
  factContacts: any[] = [];
  factTasks: any[] = [];
  loading: boolean = true;
  jFilter: finalFilterList[] = [];
  isGrouping: boolean = false;
  groupinglist: any[] = [];
  Groupby: string = '';
  userList: myTeamUsers[] = [];
  groupFor: string = '';
  private workspaceEventSub: Subscription;

  constructor(private readonly wsservice: WorkspaceService, private readonly cdr: ChangeDetectorRef,
    private readonly common: CommonService, private readonly factsheetService: FactsheetService,
  ) { }

  ngOnInit() {
    this.getFactlist(0, 0);

    if (this.onWorkspaceEvent) {
      this.workspaceEventSub = this.onWorkspaceEvent.subscribe((e: toolEvents) => {
        if (e.event === 'FILTER') {
          this.jFilter = e.data;
          this.getFactlist(0, 0);
        }
      });
    }
  }

  ngOnDestroy() {
    this.workspaceEventSub?.unsubscribe();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['isHeavily'] || changes['isCritical']) {
      this.sortfact()
    }
    this.cdr.detectChanges();
  }


  async getteam_list() {
    this.userList = await this.common.getMyTeamUsers(this.nCaseid);
  }


  async getFactlist(nContactid, nIssueid) {
    this.loading = true;
    this.factlist = [];
    this.quickfactlist = [];

    // Don't send ANY filters to backend - apply all filtering locally
    // Backend filtering is unreliable for TYPE, ISSUE, CONTACT filters
    const serverFilter = []; // Empty filter - fetch all facts
    const [factsRes, issuesRes] = await Promise.all([
      this.wsservice.getFactlist(this.nCaseid, nContactid, nIssueid, 'ALL', serverFilter) as Promise<factlistRes[]>,
      this.wsservice.getFactIssuelist(this.nCaseid, nContactid, nIssueid, 'ALL', serverFilter)
    ]);

    this.allFacts = factsRes.filter(e => e.cFType === 'F');
    this.allQuickFacts = factsRes.filter(e => e.cFType === 'QF');

    // Attach issues and contact IDs to each fact, and map counts
    await Promise.all(this.allFacts.map(async element => {
      const issues = issuesRes.filter(e => e.nFSid === element.nFSid);
      (element as any).flatIssues = issues;
      (element as any).issues = issues;

      // Preserve contact emails and IDs for filtering
      (element as any).jContactEmails = (element as any).jContactEmails || [];
      (element as any).jContactids = (element as any).jContactids || (element as any).jContactIds || [];

      // Map counts from API response (matching backend keys)
      element.nContactcount = Number((element as any).nTotalContacts || (element as any).nContactcount || 0);
      element.nTaskcount = Number((element as any).nTotalTasks || (element as any).nTaskcount || 0);
      element.nLinkscount = Number((element as any).nTotalLinks || (element as any).nLinkscount || 0);

      this.relavanceImpactFilter(element, issues);
    }));
    await Promise.all(this.allQuickFacts.map(async element => {
      const issues = issuesRes.filter(e => e.nFSid === element.nFSid);
      (element as any).flatIssues = issues;
      (element as any).issues = issues;

      // Preserve contact emails and IDs for filtering
      (element as any).jContactEmails = (element as any).jContactEmails || [];
      (element as any).jContactids = (element as any).jContactids || (element as any).jContactIds || [];

      // Map counts from API response (matching backend keys)
      element.nContactcount = Number((element as any).nTotalContacts || (element as any).nContactcount || 0);
      element.nTaskcount = Number((element as any).nTotalTasks || (element as any).nTaskcount || 0);
      element.nLinkscount = Number((element as any).nTotalLinks || (element as any).nLinkscount || 0);

      this.relavanceImpactFilter(element, issues);
    }));

    // Server-Side Filtering: API returns data filtered by what it supports.
    // We update allFacts with this data.
    // Then we apply local filter to handle any filters the backend might not support (like NOTE, Search, etc.)
    // but SKIP Contact filter locally (as backend handles it and we lack IDs).

    this.applyLocalFilter();

    this.OnEvent.emit({ event: 'Length', data: [this.factlist.length, this.quickfactlist.length] });
    this.loading = false;
    this.cdr.detectChanges();
  }

  applyLocalFilter() {
    // Debug: log contact filter and fact contact IDs
    // const contactFilter = this.jFilter.find(f => f.name === 'CONTACT' && f.value?.length);
    // If no filter, show all
    if (!this.jFilter?.length) {
      this.factlist = [...this.allFacts];
      this.quickfactlist = [...this.allQuickFacts];
      return;
    }

    const matches = (fact, filter) => {
      for (const f of filter) {
        if (f.name === 'IMPACT' && f.value?.length) {
          if (!fact.issues?.some(i =>
            f.value.map(String).includes(String(i.nImpactid)) ||
            f.value.map(String).includes(String(i.cImpact))
          )) return false;
        }
        if (f.name === 'RELEVANCE' && f.value?.length) {
          if (!fact.issues?.some(i =>
            f.value.map(String).includes(String(i.nRelevanceid)) ||
            f.value.map(String).includes(String(i.cRelevance))
          )) return false;
        }
        if (f.name === 'TYPE' && f.value?.length) {
          if (!f.value.map(String).includes(String(fact.cFiletype))) return false;
        }
        if (f.name === 'ISSUE' && f.value?.length) {
          if (!fact.issues?.some(i =>
            f.value.map(String).includes(String(i.nIssueid)) ||
            f.value.map(String).includes(String(i.cIName))
          )) return false;
        }
        if (f.name === 'CONTACT' && f.value?.length) {
          // Local contact filtering using cEmails string field
          // The selected contact emails are in f.value, and fact.cEmails contains comma-separated emails
          const selectedEmails = f.value.map(String).map(e => e.toLowerCase());

          if (!fact.cEmails) {
            // If fact has no contacts, exclude it when contact filter is active
            return false;
          }

          // Split cEmails by comma/semicolon and check if any match
          const factEmails = String(fact.cEmails).split(/[,;]/).map(e => e.trim().toLowerCase()).filter(Boolean);
          const hasMatch = factEmails.some(factEmail =>
            selectedEmails.includes(factEmail)
          );

          if (!hasMatch) {
            return false;
          }
        }
        if (f.name === 'STATUS' && f.value?.length) {
          if (!f.value.includes(fact.nStatusid)) return false;
        }
        if (f.name === 'FILETYPE' && f.value?.length) {
          if (!f.value.includes(fact.nFiletypeid)) return false;
        }
        if (f.name === 'DATE' && f.value) {
          const d = new Date(fact.dCreatedt);
          if (f.value.start && d < new Date(f.value.start)) return false;
          if (f.value.end && d > new Date(f.value.end)) return false;
        }
        if (f.name === 'CREATOR' && f.value?.length) {
          if (!f.value.includes(fact.nCreatedby)) return false;
        }
        if (f.name === 'SEARCH' && f.value) {
          const search = String(f.value).toLowerCase();
          if (!(fact.cFact?.toLowerCase().includes(search) || fact.cFilename?.toLowerCase().includes(search))) return false;
        }
        if (f.name === 'NOTE' && f.value) {
          const noteSearch = String(f.value).toLowerCase();
          const cFactMatch = fact.cFact?.toLowerCase().includes(noteSearch);
          const jTextsMatch = Array.isArray(fact.jTexts) && fact.jTexts.some(t => String(t).toLowerCase().includes(noteSearch));
          if (!cFactMatch && !jTextsMatch) return false;
        }
        if (f.name === 'COMPLETENESS' && f.value?.length) {
          // Check if fact is missing ALL of the selected completeness criteria (AND logic)
          // Record must be missing every selected field to be included
          for (const key of f.value) {
            let isMissing = false;
            if (key === 'missingEvent') {

              const hasValidDate = fact.jDate?.record &&
                                   Array.isArray(fact.jDate.record) &&
                                   fact.jDate.record.some((r: any) => {
                                     if (!r) return false;
                                     if (r.date && r.date.trim() !== '') return true;
                                     if ((r.month && r.month.trim() !== '') || (r.year && r.year.trim() !== '')) return true;
                                     return false;
                                   });
              if (!hasValidDate) {
                isMissing = true;
              }
            }
            if (key === 'missingType' && (!fact.cFiletype || fact.cFiletype.trim() === '')) {
              isMissing = true;
            }
            if (key === 'missingNote') {
              // Check if note is missing in both cFact and jTexts
              const hasCFact = fact.cFact && fact.cFact.trim() !== '';
              const hasJTexts = Array.isArray(fact.jTexts) &&
                                fact.jTexts.some(t => t && String(t).trim() !== '');
              if (!hasCFact && !hasJTexts) {
                isMissing = true;
              }
            }
            if (key === 'missingIssues' && (!fact.issues || fact.issues.length === 0)) {
              isMissing = true;
            }
            if (key === 'missingImpact' && (!fact.issues || fact.issues.length === 0 || !fact.nImpactid)) {
              isMissing = true;
            }
            if (key === 'missingRelevance' && (!fact.issues || fact.issues.length === 0 || !fact.cRelevance || fact.cRelevance.trim() === '')) {
              isMissing = true;
            }
            if (key === 'missingSource' && (!fact.cFilename || fact.cFilename.trim() === '')) {
              isMissing = true;
            }
            if (key === 'missingContacts' && (!fact.nContactcount || fact.nContactcount === 0)) {
              isMissing = true;
            }
            if (key === 'missingTasks' && (!fact.nTaskcount || fact.nTaskcount === 0)) {
              isMissing = true;
            }
            if (key === 'missingLinks' && (!fact.nLinkscount || fact.nLinkscount === 0)) {
              isMissing = true;
            }
            // If this selected field is NOT missing, exclude this record
            if (!isMissing) return false;
          }
        }
      }
      return true;
    };

    this.factlist = this.allFacts.filter(f => matches(f, this.jFilter));
    this.quickfactlist = this.allQuickFacts.filter(f => matches(f, this.jFilter));
  }

  async getIssuels(nContactid: string, nIssueid: string) {
    const res: any = await this.wsservice.getFactIssuelist(this.nCaseid, nContactid, nIssueid, 'ALL', this.jFilter);
    this.factlist.forEach(element => {
      const issues = res.filter(e => e.nFSid === element.nFSid);
      element.issues = issues;
      this.relavanceImpactFilter(element, issues);
    });
    this.quickfactlist.forEach(element => {
      const issues = res.filter(e => e.nFSid === element.nFSid);
      element.issues = issues;
      this.relavanceImpactFilter(element, issues);
    })
    this.sortfact();
    this.cdr.detectChanges();
  }

  relavanceImpactFilter(fact, issues) {
    if (issues.length) {

      let max = issues.reduce((prev, current) => (prev.nRelevanceseq > current.nRelevanceseq) ? prev : current);
      fact.nRelevancecount = issues.filter(e => e.nRelevanceid === max.nRelevanceid).length;
      fact.cRelevance = max.cRelevance;
    }
    if (issues.length) {
      let max = issues.reduce((prev, current) => (prev.nImpactseq > current.nImpactseq) ? prev : current);
      fact.nImpactcount = issues.filter(e => e.nImpactid === max.nImpactid).length;
      fact.nImpactid = max.nImpactid;
    }
    if (issues.length) {
      fact.issuesSort = issues.map(e => e.cIName || '').join(', ').trim();
    } else {
      fact.issuesSort = '';
    }
    return fact;
  }


  groupIssueCategory(issues) {
    const issuecategory: IssuecategoryRes[] = [];
    issues.forEach(element => {
      if (issuecategory.length === 0) {
        issuecategory.push({ nICid: element.nICid, cCategory: element.cCategory, sublist: [element] });
      } else {
        const index = issuecategory.findIndex(e => e.nICid === element.nICid);
        if (index > -1) {
          issuecategory[index].sublist.push(element);
        } else {
          issuecategory.push({ nICid: element.nICid, cCategory: element.cCategory, sublist: [element] });
        }
      }
    });
    return issuecategory;
  }

  async getFactfile(nContactid: string, nIssueid: string) {
    const res: FactfileRes[] = await this.wsservice.getFactfilelist(this.nCaseid, nContactid, nIssueid, 'ALL', this.jFilter);
    this.factlist.forEach(element => {
      const file: FactfileRes[] = res.filter(e => e.nFSid === element.nFSid);
      element.linkfile = file
    });
    this.quickfactlist.forEach(element => {
      const file: FactfileRes[] = res.filter(e => e.nFSid === element.nFSid);
      element.linkfile = file
    });
    this.cdr.detectChanges();
  }

  openFactSheet(fact: factlistRes) {
    // Open Fact Sheet and close PDF sidebar
    this.selectedFact = fact;
    this.showsource = null;
    this.selectedIssues = (fact as any).flatIssues || [];
    this.loadSidebarDetails(fact);
    this.cdr.detectChanges();
  }

  closeFactSheet() {
    this.selectedFact = null;
    this.selectedIssues = [];
    this.factLinks = [];
    this.factContacts = [];
    this.factTasks = [];
    this.cdr.detectChanges();
  }

  private async loadSidebarDetails(fact: factlistRes) {
    const nFSid = fact?.nFSid;
    if (!nFSid) {
      this.factLinks = [];
      this.factContacts = [];
      this.factTasks = [];
      return;
    }

    try {
      await Promise.all([
        this.loadFactLinks(nFSid),
        this.loadFactContacts(nFSid),
        this.loadFactTasks(nFSid)
      ]);
    } catch {
      this.factLinks = [];
      this.factContacts = [];
      this.factTasks = [];
    }
    this.cdr.detectChanges();
  }

  private async loadFactLinks(nFSid: string) {
    this.factLinks = [];
    try {
      const res: any = await this.factsheetService.getFactLinks<any[]>(nFSid);
      if (res && Array.isArray(res.value)) {
        this.factLinks = res.value;
      } else if (Array.isArray(res)) {
        this.factLinks = res;
      } else {
        this.factLinks = [];
      }
    } catch {
      this.factLinks = [];
    }
  }

  private async loadFactContacts(nFSid: string) {
    this.factContacts = [];
    try {
      const res: any = await this.factsheetService.getFactContacts<any[]>(nFSid);
      if (res && Array.isArray(res.value)) {
        this.factContacts = res.value;
      } else if (Array.isArray(res)) {
        this.factContacts = res;
      } else {
        this.factContacts = [];
      }
    } catch {
      this.factContacts = [];
    }
  }

  private async loadFactTasks(nFSid: string) {
    this.factTasks = [];
    try {
      const res: any = await this.factsheetService.getFactTasks<any[]>(nFSid);
      let blocks: any = res;
      if (res && Array.isArray(res.value)) {
        blocks = res.value;
      }

      const tasks = Array.isArray(blocks) && Array.isArray(blocks[0]) ? blocks[0] : blocks;
      const teams = Array.isArray(blocks) && Array.isArray(blocks[1]) ? blocks[1] : [];
      const reminders = Array.isArray(blocks) && Array.isArray(blocks[2]) ? blocks[2] : [];

      this.factTasks = tasks || [];

      if (this.factTasks?.length) {
        for (const t of this.factTasks) {
          t.teamlist = [];
          const relatedTeams = teams.filter((a: any) => a.nTaskid === t.nTaskid);
          const reminder = reminders.find((a: any) => a.nTaskid === t.nTaskid);
          if (relatedTeams?.length) {
            t.teamlist = relatedTeams;
          }
          if (reminder) {
            t.dReminderDt = reminder.dReminderDt;
          }
        }
      }
    } catch {
      this.factTasks = [];
    }
  }

  getContactInitials(c: any): string {
    if (!c) {
      return '';
    }
    const first = c.cFname ? c.cFname.charAt(0) : '';
    const last = c.cLname ? c.cLname.charAt(0) : '';
    return (first + last).toUpperCase();
  }


  isOBJ(vl) {
    if (vl && vl !== '') {
      if (Object.keys(vl).length) {
        return Object.keys(vl);
      }
    }
    return false;
  }


  removeGroup() {
    this.isGrouping = false;
    this.groupinglist = [];
    this.groupFor = '';
  }

  OnTableEvent(e: any, flag: string) {
    if (e.event === 'OPEN-PDF-SIDEBAR') {
      // Open PDF sidebar and close Fact Sheet
      this.showsource = e.data;
      this.selectedFact = null;
      this.cdr.detectChanges();
      return;
    }
    // ...existing code...
    if (e.event === 'SORT') {
      const col = e.data.col;
      let typ: 'asc' | 'desc' | 'G';
      if (e.data.col.typ === 'A') {
        typ = 'asc';
      } else if (e.data.col.typ === 'D') {
        typ = 'desc';
      } else {
        typ = 'G';
      }
      if (typ === 'G') {
        this.groupFor = flag;
        this.isGrouping = true;
        this.groupinglist = [];
        if (col.clmn === 'R' || col.clmn === 'I') {
          for (const n of flag === 'F' ? this.factlist : this.quickfactlist) {
            let obj: any = {};
            if (col.clmn === 'R') {
              this.Groupby = 'Relevance';

              for (const i of n.issues) {
                for (const issue of i.sublist) {
                  if (issue.nRelevanceid) {
                    obj = { id: issue.nRelevanceid, name: issue.cRelevance };
                    if (Object.keys(obj).length) {
                      const ins = this.groupinglist.findIndex(m => m.id === obj.id);
                      if (ins >= 0) {
                        if (!this.groupinglist[ins]["factlist"].some(m => m.nFSid === n.nFSid)) {
                          this.groupinglist[ins]["factlist"].push(n);
                        }
                      } else {
                        this.groupinglist.push({ id: obj.id, name: obj.name, factlist: [n] });
                      }
                    }
                    // break;
                  }
                }
              }
            } else if (col.clmn === 'I') {
              this.Groupby = 'Impact';
              for (const i of n.issues) {
                for (const issue of i.sublist) {
                  if (issue.nImpactid) {
                    obj = { id: issue.nImpactid, name: issue.cImpact };
                    if (Object.keys(obj).length) {
                      const ins = this.groupinglist.findIndex(m => m.id === obj.id);
                      if (ins >= 0) {
                        if (!this.groupinglist[ins]["factlist"].some(m => m.nFSid === n.nFSid)) {
                          this.groupinglist[ins]["factlist"].push(n);
                        }
                      } else {
                        this.groupinglist.push({ id: obj.id, name: obj.name, factlist: [n] });
                      }
                    }
                  }
                }
              }
            }
          }
        }

        else if (col.clmn === 'F') {
          this.Groupby = 'Level type';
          this.groupinglist = [{
            "id": 1,
            "name": "File level",
            "factlist": []
          }, {
            "id": 2,
            "name": "Text level",
            "factlist": []
          }, {
            "id": 3,
            "name": "Range level",
            "factlist": []
          }];

          for (const n of flag === 'F' ? this.factlist : this.quickfactlist) {
            try {
              if (n.jLinktype.type !== 'F' && n.cType === 'M') {
                if (!this.groupinglist[2]["factlist"].some(m => m.nFSid === n.nFSid)) {
                  this.groupinglist[2]["factlist"].push(n);
                }
              } else if (n.jLinktype?.type === 'F' && n.cType === 'M') {
                if (!this.groupinglist[0]["factlist"].some(m => m.nFSid === n.nFSid)) {
                  this.groupinglist[0]["factlist"].push(n);
                }
              } else if (n.cType !== 'M') {
                if (!this.groupinglist[1]["factlist"].some(m => m.nFSid === n.nFSid)) {
                  this.groupinglist[1]["factlist"].push(n);
                }
              }
            } catch (error) {
              // Log or handle error appropriately
            }
          }
        }
        if (!this.groupinglist.length) {
          this.groupFor = '';
          this.isGrouping = false;
        }
        if (col.clmn === 'F') {
          let isdata: boolean = false
          this.groupinglist.forEach(e => {
            if (e.factlist.length) {
              isdata = true
            }
          });
          this.isGrouping = isdata;
        }
        return;
      }

      let clmn: string;
      if (col.clmn === 'topimpact_ind') {
        clmn = 'nImpactid';
      } else if (col.clmn === 'toprelevance_ind') {
        clmn = 'cRelevance';
      } else {
        clmn = col.clmn;
      }

      const dir = typ === 'asc' ? 1 : -1;

      const sortFn = (a: any, b: any) => {
        const aRaw = a[clmn];
        const bRaw = b[clmn];

        // Null / undefined to the end (matches prototype)
        if (aRaw === null || aRaw === undefined) return 1;
        if (bRaw === null || bRaw === undefined) return -1;

        // Date handling for created/event
        if (clmn === 'dCreateDt') {
          const da = aRaw instanceof Date ? aRaw : new Date(aRaw);
          const db = bRaw instanceof Date ? bRaw : new Date(bRaw);
          if (!Number.isNaN(da.getTime()) && !Number.isNaN(db.getTime())) {
            return (da.getTime() - db.getTime()) * dir;
          }
        }

        // Numbers
        if (typeof aRaw === 'number' && typeof bRaw === 'number') {
          return (aRaw - bRaw) * dir;
        }

        // Strings (noteSort, issuesSort, cRelevance, cFilename, etc.)
        if (typeof aRaw === 'string' && typeof bRaw === 'string') {
          return aRaw.localeCompare(bRaw) * dir;
        }

        // Arrays (fallback: sort by length)
        if (Array.isArray(aRaw) && Array.isArray(bRaw)) {
          return (aRaw.length - bRaw.length) * dir;
        }
        if (Array.isArray(aRaw)) return 1;
        if (Array.isArray(bRaw)) return -1;

        // Fallback: keep order
        return 0;
      };

      if (flag === 'F') {
        this.factlist = [...this.factlist].sort(sortFn);
      } else {
        this.quickfactlist = [...this.quickfactlist].sort(sortFn);
      }

      this.cdr.detectChanges();


    } else if (e.event === 'SUBMIT-NOTE') {
      const int = this[this.isFact ? 'factlist' : 'quickfactlist'].findIndex(j => j.nFSid === e.data.nFSid)
      if (int > -1) {
        this[this.isFact ? 'factlist' : 'quickfactlist'][int].jTexts = e.data.jTexts;
      }

    } else {
      this.OnEvent.emit(e);
    }
  }


  sortfact(): void {
    this.factlist.sort((a, b) => {
      const aImpact = a?.issues[0]?.['nImpactseq'] ?? Number.MAX_SAFE_INTEGER;
      const bImpact = b?.issues[0]?.['nImpactseq'] ?? Number.MAX_SAFE_INTEGER;
      if (this.isHeavily) {
        return aImpact - bImpact;
      } else {
        return aImpact + bImpact;
      }
    });

    this.quickfactlist.sort((a, b) => {
      const aImpact = a?.issues[0]?.['nImpactseq'] ?? Number.MAX_SAFE_INTEGER;
      const bImpact = b?.issues[0]?.['nImpactseq'] ?? Number.MAX_SAFE_INTEGER;
      if (this.isHeavily) {
        return aImpact - bImpact;
      } else {
        return aImpact + bImpact;
      }
    });


    this.factlist.sort((a, b) => {
      const aRelevance = a?.issues[0]?.['nRelevanceseq'] ?? Number.MAX_SAFE_INTEGER;
      const bRelevance = b?.issues[0]?.['nRelevanceseq'] ?? Number.MAX_SAFE_INTEGER;
      if (this.isCritical) {
        return aRelevance - bRelevance;
      } else {
        return aRelevance + bRelevance;
      }
    });
    this.quickfactlist.sort((a, b) => {
      const aRelevance = a?.issues[0]?.['nRelevanceseq'] ?? Number.MAX_SAFE_INTEGER;
      const bRelevance = b?.issues[0]?.['nRelevanceseq'] ?? Number.MAX_SAFE_INTEGER;
      if (this.isCritical) {
        return aRelevance - bRelevance;
      } else {
        return aRelevance + bRelevance;
      }
    });
  }



  trackByFn(index: any, item: any): any {
    return item.nFSid || index;
  }

  getRelevanceColor(relevance: string | null | undefined): string {
    if (!relevance) {
      return '#6b7280'; // neutral gray
    }
    const v = relevance.toLowerCase();
    if (v === 'critical') {
      return '#ef4444';
    }
    if (v === 'high') {
      return '#f59e0b';
    }
    if (v === 'medium') {
      return '#10b981';
    }
    if (v === 'low') {
      return '#60a5fa';
    }
    return '#6b7280';
  }
}
